    "tags": [
      "resume keywords",
      "ATS optimization",
      "keyword research",
      "resume strategy"
    ],
    "difficulty": "Beginner",
    "readTime": "12 min read",
    "authorName": "Career Development Team",
    "authorTitle": "Recruitment & ATS Specialist",
    "publishedAt": "2024-03-10",
    "featuredImage": "https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=800&q=80"
